-- YG-1069: FR-OPS-003 İlk Kapsam, Hizmet Branşı ve Çıktı Tanımı; Dosya Sorumlusu doldurur, Teknik Uzman tamamlar ve kontrol eder; dış taraflar görmez.
CREATE TABLE ilk_kapsam (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), surum integer NOT NULL, varlik_sistem text NOT NULL, faaliyet text NOT NULL, teknik_brans text[] NOT NULL CHECK (cardinality(teknik_brans) > 0), koordinator_ref text REFERENCES kullanici_hesabi (kimlik), destek_isleri text, beklenen_cikti text NOT NULL, kabul_olcutu text NOT NULL, hariclar text NOT NULL, varsayimlar text, durum text NOT NULL DEFAULT 'Kontrolde' CHECK (durum IN ('Kontrolde', 'Onaylı', 'İade Edildi', 'Yerine Geçti')), olusturan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), kontrol_eden_ref text REFERENCES kullanici_hesabi (kimlik), kontrol_zamani timestamptz, iade_gerekcesi text, olusturma_zamani timestamptz NOT NULL DEFAULT now(), guncelleme_zamani timestamptz NOT NULL DEFAULT now(), UNIQUE (dosya_ref, surum), CHECK (cardinality(teknik_brans) = 1 OR koordinator_ref IS NOT NULL));
GRANT SELECT, INSERT, UPDATE ON ilk_kapsam TO yatonet_uygulama;
